        if len(values) == 1:
            return [values]
        differences = [values[i + 1] - values[i] for i in range(len(values) - 1)]
        return [values] + generate_difference_table(differences)

    def find_degree(difference_table):
        for i, row in enumerate(difference_table):
            if any(row):
                return i
        return len(difference_table)

    def predict_next_value(difference_table, degree):
        for i in range(degree, 0, -1):
            difference_table[i].append(difference_table[i][-1] + difference_table[i - 1][-1])
        return difference_table[degree][-1]

    difference_table = generate_difference_table(values)
    degree = find_degree(difference_table)
    next_value = predict_next_value(difference_table, degree)
    return degree, next_value

