    def calculate_differences(vals):
        return [vals[i + 1] - vals[i] for i in range(len(vals) - 1)]

    def find_degree(diffs):
        degree = 0
        while all(d == diffs[0] for d in diffs):
            degree += 1
            diffs = calculate_differences(diffs)
            if len(diffs) < 2:
                break
        return degree

    def newton_divided_differences(x, x_values, y_values):
        n = len(y_values)
        coef = list(y_values)
        for j in range(1, n):
            for i in range(n - 1, j - 1, -1):
                coef[i] = (coef[i] - coef[i - 1]) / (x_values[i] - x_values[i - j])
        return coef

    def evaluate_polynomial(coef, x, x_values):
        n = len(coef)
        result = coef[0]
        for i in range(1, n):
            term = coef[i]
            for j in range(i):
                term *= (x - x_values[j])
            result += term
        return result

    x_values = list(range(n))
    degree = find_degree(values)
    coef = newton_divided_differences(n, x_values, values)
    next_value = evaluate_polynomial(coef, n, x_values)

    print(degree, int(next_value))

